// VisaCheck global rules data — multi-country, multi-category published-rule data
// with PENDING_HUMAN_CLICK markers, official authorities, lastUpdated / effectiveFrom dates,
// and proposed-change metadata.
//
// STORE-NOTHING: this module is pure data, no I/O. Used by the in-memory rules engine only.
// Add new rules by appending to RULES. Every rule MUST ship with `status: "PENDING_HUMAN_CLICK"`
// until a human clicks through the official authority's published page and pastes verbatim wording.

import type { Lang } from '@/lib/i18n';

export type RuleCategory = 'skilled_worker' | 'student' | 'visitor' | 'family' | 'business' | 'investor';

export interface RuleAuthority {
  shortName: string;          // e.g. "UKVI", "USCIS", "IRCC", "Home Affairs", "BAMF", "ICP"
  officialName: string;       // e.g. "UK Visas and Immigration"
  url: string;                // https URL to the official guidance
}

export interface ProposedChange {
  status: 'consultation' | 'proposed' | 'announced' | 'deferred';
  summary: string;            // human-readable description of the upcoming change
  expectedEffectiveAt: string; // ISO date string
  sourceUrl: string;           // link to the announcement
}

export interface Rule {
  id: string;                  // unique within (countryIso, category)
  countryIso: string;          // "GB" | "US" | "CA" | "AU" | "DE" | "AE"
  category: RuleCategory;
  // The status marker — gate is: JSON.stringify(rule).includes('PENDING_HUMAN_CLICK')
  status: 'PENDING_HUMAN_CLICK';
  authority: RuleAuthority;
  lastUpdated: string;         // ISO date the rule data was last reviewed
  effectiveFrom: string;       // ISO date the rule became effective
  validTo?: string | null;     // ISO date the rule expires (null = open-ended)
  title: { en: string; ur: string; bn: string };
  summary: { en: string; ur: string; bn: string };
  source: string;              // https URL to the official published rule
  proposedChange?: ProposedChange;
  // Pure logical evaluator. Result is masked by the gate — if status is PENDING_HUMAN_CLICK,
  // the user always sees "pending" (the safe "being verified" state).
  applies: (a: Answers) => boolean;
  evaluate: (a: Answers) => 'pass' | 'fail' | 'na';
}

export interface Answers {
  // Personal profile — asked first, applies to all countries/categories
  age: number;                      // applicant age (for points calculation)
  education: 'secondary' | 'diploma' | 'bachelor' | 'master' | 'doctorate' | '';
  maritalStatus: 'single' | 'married' | 'partner' | '';
  employmentStatus: 'employed' | 'self_employed' | 'student' | 'unemployed' | '';
  workExperienceYears: number;      // total years of professional experience
  // Nationality + location
  nationality: string;            // ISO country name
  applyingFromOutsideUK: boolean;
  // Job details — country-specific
  jobTitle: string;
  socCode: string;
  salary: number;                 // gross annual, in destination currency
  hasCos: boolean;                // certificate of sponsorship / job offer
  sponsorLicensed: 'yes' | 'unsure' | 'no';
  newEntrant: boolean;
  englishMet: boolean;
  fundsMet: boolean;
  ihsAware: boolean;
  criminalCert: boolean;
  passportValid: boolean;
  // Extended for other visa categories
  admissionOffer: boolean;        // student: has school admission
  studyFundsMet: boolean;         // student: tuition + living funds
  relationshipProof: boolean;     // family: proof of relationship to settled person
  sponsorIncomeMet: boolean;      // family: sponsor meets income threshold
  businessPlan: boolean;          // business/investor: has business plan
  investmentAmount: number;       // investor: capital to invest (in destination currency)
  visitPurposeValid: boolean;     // visitor: stated purpose allowed
  returnTicket: boolean;          // visitor: has return/onward ticket
  healthInsurance: boolean;        // visitor: has travel insurance
}

