// Helpers — used by the engine to filter rules by country + category.
export function rulesForCountryCategory(countryIso: string, category: RuleCategory): Rule[] {
  const iso = countryIso.trim().toUpperCase();
  return RULES.filter((r) => r.countryIso === iso && r.category === category);
}

export function rulesForCountry(countryIso: string): Rule[] {
  const iso = countryIso.trim().toUpperCase();
  return RULES.filter((r) => r.countryIso === iso);
}

export function rulesCount(countryIso?: string): number {
  if (!countryIso) return RULES.length;
  return rulesForCountry(countryIso).length;
}

// Date validity check — true if today falls within [effectiveFrom, validTo].
export function isRuleActive(rule: Rule, now: Date = new Date()): boolean {
  const from = new Date(rule.effectiveFrom).getTime();
  const to = rule.validTo ? new Date(rule.validTo).getTime() : Infinity;
  const n = now.getTime();
  return n >= from && n <= to;
}
